require 'spec_helper'

describe "Search Page Parsing" do

  describe "Default Page - Small Carrousel" do
    specify "Michelangelo" do
      parser = GoogleSearchPageCrawler.new
      result = JSON.parse(parser.crawl(fixture_file_path("michelangelo-search.html")))
      expected_artworks = JSON.parse(load_fixture_file("van-gogh-expected-parse-response.json"))["artworks"]

      puts result["artworks"].map { |artwork| artwork["name"] }
      expect(result["artworks"].size).to eq(6)
      expect(result["artworks"][0]["name"]).to eq("Sistine Chapel ceiling")
      expect(result["artworks"][0]["extensions"]).to eq(["1512"])
      expect(result["artworks"][0]["link"]).to eq("https://www.google.com/search?sca_esv=e77f9c08ad4d25ad&biw=1359&bih=1020&sxsrf=AE3TifN6hlk5lKx8fxUHFbtseempaERpvQ:1755203879937&q=Sistine+Chapel+ceiling&stick=H4sIAAAAAAAAAONgFuLQz9U3MLUoN1XiBLGMzUqSkrWUspOt9Msyi0sTc-ITi0qQmJnFJVbl-UXZxYtYxYKBnMy8VAXnjMSC1ByF5NTMnMy8dABzqHXRVAAAAA&sa=X&ved=2ahUKEwjXrZb-k4uPAxWqFbkGHZd2JZkQgOQBegQIJxAG")
      expect(result["artworks"][0]["image"]).to eq("data:image/jpeg;base64,")

      expect(result["artworks"].last["name"]).to eq("Mosè di Michelangelo")
    end
  end
end
